# dotfiles.map — repo-path -> install-path mapping for everything this repo
# deploys onto the server outside of $HOME (i.e. beyond what dotfiles-setup /
# scripts-link already keep in sync as plain symlinks).
#
# Columns (whitespace-separated, repo_path/install_path may not contain spaces):
#   type          owner        repo_path                              install_path
#
# type:
#   symlink  - install_path IS a symlink into this repo. Zero drift possible;
#              dotdrift just verifies the symlink still points here.
#   copy     - install_path is a separate root-owned (or daemon-consumed)
#              copy, installed deliberately via `sudo cp` (or `visudo -cf`,
#              `crontab`, etc). dotdrift diffs repo vs install_path content.
#   copy-secret - same as copy, but the repo copy deliberately has secrets
#              redacted (passwords, keys), so content will never match live.
#              dotdrift only checks that install_path exists.
#   crontab  - install_path is "matt" or "root": diff repo file against
#              that user's live `crontab -l`, not a filesystem path.
#   exclude  - not managed by this repo (docker-repo or distro-owned unit).
#              Listed only so the unmapped-file scan doesn't flag it.
#
# owner: dotfiles | docker-repo | distro
#
# Why some scripts are "copy" and not "symlink" despite being scripts:
#   upssched-cmd runs as the unprivileged `nut` user (RUN_AS_USER in
#   upsmon.conf), and /home/matt is mode 700 — `nut` has no traversal rights
#   into the repo. Symlinking it would require loosening that, which is not
#   worth it for one file. Kept as a deliberate copy instead.
#   send-alert (added 2026-07-03): same rationale — upssched-cmd calls it as
#   the nut user, so it must be traversable without going through /home/matt.
#   msmtp-alert-queue (added 2026-07-04, installed as /usr/local/bin/msmtp):
#   same rationale again — nut invokes bare `msmtp` too (upssched-cmd), so
#   the shim it resolves to via $PATH can't be a symlink through /home/matt.
# Why NUT/msmtp/wg0 config and all systemd units stay "copy":
#   these are read at daemon startup (or need `daemon-reload`/a coordinated
#   restart to take effect either way), so a symlink buys no convenience —
#   it would just let `fdotl`'s hard reset silently mutate live daemon state
#   with no review step. See feedback_nut_server_restart_danger memory.

# --- scripts: root/matt-invoked, safe to symlink (root bypasses DAC; matt owns $HOME) ---
symlink  dotfiles  scripts/server/alert-digest-flush          /usr/local/bin/alert-digest-flush
symlink  dotfiles  scripts/server/arr-pipeline-check.sh        /usr/local/bin/arr-pipeline-check.sh
symlink  dotfiles  scripts/server/docker-health-monitor.sh   /usr/local/bin/docker-health-monitor.sh
symlink  dotfiles  scripts/server/docker-state-backup.sh     /usr/local/bin/docker-state-backup.sh
symlink  dotfiles  scripts/server/health-monitor.sh          /usr/local/bin/health-monitor.sh
symlink  dotfiles  scripts/server/ntfy-reboot-required       /usr/local/bin/ntfy-reboot-required
symlink  dotfiles  scripts/server/nut-apt-hook                /usr/local/bin/nut-apt-hook
symlink  dotfiles  scripts/server/secrets-backup              /usr/local/bin/secrets-backup
symlink  dotfiles  scripts/server/send-mail                   /usr/local/bin/send-mail
symlink  dotfiles  scripts/server/ssh-watchdog.sh              /usr/local/bin/ssh-watchdog.sh
symlink  dotfiles  scripts/server/temp-monitor.sh              /usr/local/bin/temp-monitor.sh
symlink  dotfiles  scripts/server/ups-battery-health.sh        /usr/local/bin/ups-battery-health.sh
symlink  dotfiles  scripts/server/wait-for-tailscale.sh        /usr/local/bin/wait-for-tailscale.sh
symlink  dotfiles  scripts/server/wg0-down-extra.sh            /usr/local/bin/wg0-down-extra.sh
symlink  dotfiles  scripts/server/wg0-prestart.sh              /usr/local/bin/wg0-prestart.sh
symlink  dotfiles  scripts/server/wg0-up-extra.sh              /usr/local/bin/wg0-up-extra.sh
symlink  dotfiles  scripts/server/wg-watchdog.sh                /usr/local/bin/wg-watchdog.sh
symlink  dotfiles  scripts/server/qbt-natpmp-renew.sh           /usr/local/bin/qbt-natpmp-renew.sh
symlink  dotfiles  scripts/server/fleet-update-digest           /usr/local/bin/fleet-update-digest
symlink  dotfiles  scripts/server/nut-tailscale-listen.sh        /usr/local/bin/nut-tailscale-listen.sh
symlink  dotfiles  scripts/server/tailscale-ready-selfheal.sh    /usr/local/bin/tailscale-ready-selfheal.sh

# --- scripts that must stay a copy: reached by the unprivileged `nut` user ---
copy     dotfiles  scripts/server/upssched-cmd                 /usr/bin/upssched-cmd
copy     dotfiles  scripts/server/send-alert                    /usr/local/bin/send-alert
copy     dotfiles  scripts/server/msmtp-alert-queue              /usr/local/bin/msmtp

# --- NUT config: daemon-read at startup, needs coordinated restart ---
copy     dotfiles  server-configs/nut/nut.conf                 /etc/nut/nut.conf
copy     dotfiles  server-configs/nut/ups.conf                 /etc/nut/ups.conf
copy     dotfiles  server-configs/nut/upsd.conf                 /etc/nut/upsd.conf
copy-secret dotfiles  server-configs/nut/upsd.users             /etc/nut/upsd.users
copy-secret dotfiles  server-configs/nut/upsmon.conf             /etc/nut/upsmon.conf
copy     dotfiles  server-configs/nut/upssched.conf               /etc/nut/upssched.conf
copy     dotfiles  server-configs/nut/sudoers-nut-shutdown         /etc/sudoers.d/nut-shutdown
copy     dotfiles  server-configs/nut/nut-server.service.d/pidfile.conf    /etc/systemd/system/nut-server.service.d/pidfile.conf
copy     dotfiles  server-configs/nut/nut-server.service.d/tailscale.conf  /etc/systemd/system/nut-server.service.d/tailscale.conf

# --- other daemon config ---
copy-secret dotfiles  server-configs/msmtprc                    /etc/msmtprc
copy-secret dotfiles  server-configs/wg0.conf                    /etc/wireguard/wg0.conf
copy     dotfiles  server-configs/99nut-safe-upgrade               /etc/apt/apt.conf.d/99nut-safe-upgrade
copy     dotfiles  server-configs/99ntfy-reboot                     /etc/apt/apt.conf.d/99ntfy-reboot
copy     dotfiles  server-configs/gitconfig                        /home/matt/.gitconfig
copy     dotfiles  server-configs/gnupg-agent.conf                  /home/matt/.gnupg/gpg-agent.conf
copy     dotfiles  server-configs/ssh_allowed_signers                /home/matt/.ssh/allowed_signers
copy     dotfiles  scripts/server/logrotate-server-scripts             /etc/logrotate.d/server-scripts

# --- sudoers drop-ins (audit 2026-07-02: matt-nopasswd is the primary rule;
#     the scoped files are backstops that keep unattended paths alive if it is
#     ever tightened. A sixth file, /etc/sudoers.d/matt ("service tailscale
#     restart"), was deleted 2026-07-02: zero uses in the full journal since
#     install, SysVinit command form, nothing referenced it.) ---
copy     dotfiles  server-configs/sudoers/matt-nopasswd         /etc/sudoers.d/matt-nopasswd
copy     dotfiles  server-configs/sudoers/smartctl              /etc/sudoers.d/smartctl
copy     dotfiles  server-configs/sudoers/matt-wg               /etc/sudoers.d/matt-wg
copy     dotfiles  server-configs/sudoers/vpn-diag              /etc/sudoers.d/vpn-diag
copy     dotfiles  server-configs/sudoers/dotdrift              /etc/sudoers.d/dotdrift

# --- crontabs ---
crontab  dotfiles  server-configs/crontab                       matt
crontab  dotfiles  server-configs/root-crontab                  root

# --- systemd units (all copy: unit changes always need daemon-reload anyway) ---
# homepage-compose/ntfy-compose/pihole-compose/radicale-compose and the
# tailscale-serve-{drivetemps,homepage} units are NOT here: their canonical
# copies live in ~/docker/systemd/ (a separate repo), not this one. Dotfiles
# used to carry stale duplicates of these (see docker-CLAUDE.md history) —
# removed 2026-07-02. tailscale-serve-{qbittorrent,stirling-pdf,uptime-kuma}
# were fully deleted (not just excluded): obsolete post-tsdproxy-migration,
# not installed live, no recovery value.
copy     dotfiles  scripts/server/ssh-watchdog.service                    /etc/systemd/system/ssh-watchdog.service
copy     dotfiles  scripts/server/tailscale-ready.service                 /etc/systemd/system/tailscale-ready.service
copy     dotfiles  scripts/server/wg0.service                             /etc/systemd/system/wg0.service
copy     dotfiles  scripts/server/docker-health-monitor.service           /etc/systemd/system/docker-health-monitor.service
copy     dotfiles  scripts/server/wg-watchdog.service                     /etc/systemd/system/wg-watchdog.service
copy     dotfiles  scripts/server/qbt-natpmp-renew.service                /etc/systemd/system/qbt-natpmp-renew.service
copy     dotfiles  scripts/server/healthcheck-ping.service                /etc/systemd/system/healthcheck-ping.service
copy     dotfiles  scripts/server/healthcheck-ping.timer                  /etc/systemd/system/healthcheck-ping.timer
copy     dotfiles  scripts/server/router-stats.service                    /etc/systemd/system/router-stats.service
copy     dotfiles  scripts/server/router-stats.timer                      /etc/systemd/system/router-stats.timer
copy     dotfiles  scripts/server/router-stats-http.service                /etc/systemd/system/router-stats-http.service
copy     dotfiles  scripts/server/ups-charge-log.service                   /etc/systemd/system/ups-charge-log.service
copy     dotfiles  scripts/server/ups-charge-log.timer                     /etc/systemd/system/ups-charge-log.timer
copy     dotfiles  scripts/server/immich-ml-lockfix.service                 /etc/systemd/system/immich-ml-lockfix.service
copy     dotfiles  scripts/server/nut-tailscale-listen.service              /etc/systemd/system/nut-tailscale-listen.service
copy     dotfiles  scripts/server/tailscale-ready-selfheal.service          /etc/systemd/system/tailscale-ready-selfheal.service
copy     dotfiles  scripts/server/tailscale-ready-selfheal.timer            /etc/systemd/system/tailscale-ready-selfheal.timer
copy     dotfiles  scripts/server/route-monitor.service                     /etc/systemd/system/route-monitor.service
copy     dotfiles  scripts/server/tailscaled-override.conf                 /etc/systemd/system/tailscaled.service.d/override.conf

# --- known-live units NOT managed by this repo, so the unmapped scan skips them ---
exclude  docker-repo  -  arrs-compose.service
exclude  docker-repo  -  filebrowser-compose.service
exclude  docker-repo  -  homepage-compose.service
exclude  docker-repo  -  immich-compose.service
exclude  docker-repo  -  jellyfin-compose.service
exclude  docker-repo  -  ntfy-compose.service
exclude  docker-repo  -  pihole-compose.service
exclude  docker-repo  -  qbittorrent-compose.service
exclude  docker-repo  -  radicale-compose.service
exclude  docker-repo  -  tailscale-serve-drivetemps.service
exclude  docker-repo  -  tailscale-serve-homepage.service
exclude  docker-repo  -  tsdproxy-compose.service
exclude  docker-repo  -  watchtower-compose.service
exclude  distro       -  dbus-org.freedesktop.timesync1.service
exclude  distro       -  ip6tables.service
exclude  distro       -  iptables.service
exclude  distro       -  smartd.service
exclude  distro       -  sshd.service
exclude  distro       -  upsd.service
exclude  distro       -  upsmon.service

# --- $HOME-only scripts: already synced by scripts-link, no root install ---
exclude  dotfiles  scripts/server/planned-shutdown  scripts-link
exclude  dotfiles  scripts/server/planned-startup   scripts-link
